// Tiny hyperscript: h(type, props, ...children) with array flattening.
export const TEXT = '#text';

export function h(type, props, ...children) {
  return {
    type,
    props: props || {},
    children: flatten(children),
  };
}

function flatten(items) {
  const out = [];
  for (const item of items) {
    if (item === null || item === undefined || item === false || item === true) continue;
    if (Array.isArray(item)) {
      out.push(...flatten(item));
    } else if (typeof item === 'object') {
      // Recursively flatten object children's arrays is not needed; keep vnode as-is.
      out.push(item);
    } else {
      out.push({ type: TEXT, value: String(item), props: {}, children: [] });
    }
  }
  return out;
}

