import { TEXT } from './h.js';

const isEvent = (k) => k.startsWith('on') && k.length > 2;
const eventName = (k) => k.slice(2).toLowerCase();

export function mount(vnode, container) {
  const el = createEl(vnode);
  applyProps(el, {}, vnode.props);
  for (const child of vnode.children) mount(child, el);
  if (container) container.appendChild(el);
  return el;
}

function createEl(vnode) {
  if (vnode.type === TEXT) {
    vnode.el = document.createTextNode(vnode.value);
  } else {
    vnode.el = document.createElement(vnode.type);
  }
  return vnode.el;
}

export function patch(container, oldVnode, newVnode) {
  if (!sameType(oldVnode, newVnode)) {
    const fresh = createEl(newVnode);
    applyProps(fresh, {}, newVnode.props);
    for (const child of newVnode.children) mount(child, fresh);
    container.replaceChild(fresh, oldVnode.el);
    return fresh;
  }
  const el = (newVnode.el = oldVnode.el);
  if (newVnode.type === TEXT) {
    if (oldVnode.value !== newVnode.value) el.nodeValue = newVnode.value;
    return el;
  }
  diffProps(el, oldVnode.props, newVnode.props);
  patchChildren(el, oldVnode.children, newVnode.children);
  return el;
}

function sameType(a, b) {
  if (a.type === TEXT || b.type === TEXT) return a.type === b.type;
  return a.type === b.type;
}

// ---------- props ----------

function applyProps(el, oldProps = {}, props = {}) {
  diffProps(el, oldProps, props);
}

function diffProps(el, oldProps, newProps) {
  // removals
  for (const key of Object.keys(oldProps)) {
    if (key === 'key' || key === 'children') continue;
    if (!(key in newProps)) removeProp(el, key, oldProps[key]);
  }
  // sets / updates
  for (const key of Object.keys(newProps)) {
    if (key === 'key' || key === 'children') continue;
    const prev = oldProps[key];
    const next = newProps[key];
    if (prev === next) continue;
    if (isEvent(key)) {
      swapListener(el, eventName(key), prev, next);
    } else if (key === 'style' && typeof next === 'object' && next !== null) {
      const prevStyle = typeof prev === 'object' && prev !== null ? prev : {};
      for (const prop of Object.keys(prevStyle)) {
        if (!(prop in next)) el.style[prop] = '';
      }
      for (const prop of Object.keys(next)) {
        if (prevStyle[prop] !== next[prop]) el.style[prop] = next[prop];
      }
    } else if (key === 'value' && el instanceof HTMLInputElement) {
      el.value = next;
    } else if (key === 'className') {
      el.className = next;
    } else {
      el.setAttribute(key, next);
    }
  }
}

function removeProp(el, key, prev) {
  if (isEvent(key)) {
    swapListener(el, eventName(key), prev, undefined);
  } else if (key === 'style') {
    el.removeAttribute('style');
  } else if (key === 'className') {
    el.removeAttribute('class');
  } else {
    el.removeAttribute(key);
  }
}

function swapListener(el, type, prev, next) {
  const handlers = (el._handlers ||= {});
  if (handlers[type]) el.removeEventListener(type, handlers[type]);
  if (next) {
    el.addEventListener(type, next);
    handlers[type] = next;
  } else {
    delete handlers[type];
  }
}

// ---------- keyed children reconciliation ----------

function patchChildren(parentEl, oldChildren, newChildren) {
  const keyedOld = new Map();
  for (const c of oldChildren) {
    const k = c.props && c.props.key;
    if (k != null) keyedOld.set(k, { vnode: c, used: false });
  }
  const usedOld = new Set();
  const newEls = [];

  for (let i = 0; i < newChildren.length; i++) {
    const nv = newChildren[i];
    let matched = null;
    const nk = nv.props && nv.props.key;
    if (nk == null) {
      // positional match against the unkeyed old child at the same index
      const ov = oldChildren[i];
      if (ov && !usedOld.has(ov) && !(ov.props && ov.props.key != null) && sameType(ov, nv)) {
        matched = ov;
      }
    } else {
      const entry = keyedOld.get(nk);
      if (entry && !entry.used) matched = entry.vnode;
    }

    if (matched) {
      usedOld.add(matched);
      if (keyedOld.get(nk)) keyedOld.get(nk).used = true;
      patch(parentEl, matched, nv);
    } else {
      mount(nv, parentEl); // appended; reorder pass fixes position
    }
    newEls.push(nv.el);
  }

  // Move existing DOM nodes into the new order (no recreation).
  for (let i = 0; i < newEls.length; i++) {
    const el = newEls[i];
    const ref = parentEl.childNodes[i] ?? null;
    if (ref !== el) parentEl.insertBefore(el, ref);
  }
  // Anything left at the tail is an unmatched old node: remove it.
  while (parentEl.childNodes.length > newEls.length) {
    parentEl.removeChild(parentEl.lastChild);
  }
}

