import { describe, it, expect, vi } from 'vitest';
import { h } from '../src/h.js';
import { mount, patch } from '../src/render.js';

const click = (el) => el.dispatchEvent(new MouseEvent('click', { bubbles: true }));

describe('mini vdom', () => {
  it('mounts a tree with text and props', () => {
    const root = document.createElement('div');
    document.body.appendChild(root);
    const el = mount(h('div', { id: 'app', title: 'hi' }, 'hello ', h('b', null, 'world')), root);
    expect(el).toBe(root.firstChild);
    expect(el.getAttribute('title')).toBe('hi');
    expect(el.childNodes[0].nodeType).toBe(3);
    expect(el.textContent).toBe('hello world');
  });

  it('updates text nodes in place', () => {
    const root = document.createElement('div');
    document.body.appendChild(root);
    let vnode = h('p', null, 'before');
    const el = mount(vnode, root);
    expect(el.textContent).toBe('before');
    patch(root, vnode, (vnode = h('p', null, 'after')));
    expect(el.textContent).toBe('after');
    // same text node object reused
    expect(el.childNodes[0]).toBeTruthy();
  });

  it('diffs props including removal and style objects', () => {
    const root = document.createElement('div');
    document.body.appendChild(root);
    let vnode = h('div', {
      title: 'keep-me',
      'data-old': 'gone',
      className: 'box',
      style: { color: 'red', margin: '4px' },
    });
    const el = mount(vnode, root);
    expect(el.getAttribute('data-old')).toBe('gone');
    expect(el.style.color).toBe('red');
    expect(el.style.margin).toBe('4px');

    patch(
      root,
      vnode,
      (vnode = h('div', {
        title: 'keep-me',
        style: { color: 'blue', padding: '2px' },
      }))
    );

    expect(el.getAttribute('data-old')).toBeNull(); // prop removed
    expect(el.getAttribute('class')).toBeNull(); // className removed
    expect(el.style.color).toBe('blue'); // style updated
    expect(el.style.margin).toBe(''); // stale style key removed
    expect(el.style.padding).toBe('2px'); // style key added
    expect(el.hasAttribute('style')).toBe(true);
  });

  it('swaps event listeners without stacking', () => {
    const root = document.createElement('div');
    document.body.appendChild(root);
    const first = vi.fn();
    const second = vi.fn();
    let vnode = h('button', { onClick: first }, 'press');
    const el = mount(vnode, root);

    click(el);
    click(el);
    expect(first).toHaveBeenCalledTimes(2);

    patch(root, vnode, (vnode = h('button', { onClick: second }, 'press')));

    click(el);
    click(el);
    expect(first).toHaveBeenCalledTimes(2); // old handler no longer fires
    expect(second).toHaveBeenCalledTimes(2); // new handler fires

    // removing the listener entirely also works
    patch(root, vnode, h('button', null, 'press'));
    click(el);
    expect(second).toHaveBeenCalledTimes(2);
  });

  it('reorders keyed children by MOVING existing DOM nodes (identity preserved)', () => {
    const root = document.createElement('div');
    document.body.appendChild(root);
    const item = (key, label) => h('li', { key }, label);
    let vnode = h('ul', null, [item('a', 'A'), item('b', 'B'), item('c', 'C'), item('d', 'D')]);
    const ul = mount(vnode, root);

    const refs = Object.fromEntries(
      ['a', 'b', 'c', 'd'].map((k) => [k, ul.children[['a', 'b', 'c', 'd'].indexOf(k)]])
    );
    expect(refs.a.textContent).toBe('A');

    // shuffle: c a d b
    patch(root, vnode, (vnode = h('ul', null, [item('c', 'C'), item('a', 'A'), item('d', 'D'), item('b', 'B')])));
    const order = [...ul.children];
    expect(order[0]).toBe(refs.c);
    expect(order[1]).toBe(refs.a);
    expect(order[2]).toBe(refs.d);
    expect(order[3]).toBe(refs.b);
    for (const ref of Object.values(refs)) {
      expect(document.contains(ref)).toBe(true); // same nodes still in the document
    }

    // insert + remove while keeping identity of survivors
    const extraEl = item('e', 'E').type && (() => {})() ?? undefined;
    patch(
      root,
      vnode,
      (vnode = h('ul', null, [item('e', 'E'), item('a', 'A2'), item('b', 'B')]))
    );
    expect([...ul.children][0].textContent).toBe('E');
    expect([...ul.children][1]).toBe(refs.a); // moved, not recreated
    expect([...ul.children][2]).toBe(refs.b);
    expect([...ul.children].length).toBe(3);
    expect(document.contains(refs.c)).toBe(false); // removed from doc
    expect(refs.a.textContent).toBe('A2'); // patched in place
  });

  it('patches nested children deep inside the tree', () => {
    const root = document.createElement('div');
    document.body.appendChild(root);
    let vnode = h(
      'section',
      null,
      h('header', null, h('h1', null, 'Title')),
      h('main', null, h('p', { key: 1 }, 'one'), h('span', null, 'tail'))
    );
    const section = mount(vnode, root);
    const p = section.querySelector('p');
    const span = section.querySelector('span');

    patch(
      root,
      vnode,
      (vnode = h(
        'section',
        null,
        h('header', null, h('h1', null, 'Renamed')),
        h('main', null, h('strong', { key: 1 }, 'uno'), h('em', null, 'end'))
      ))
    );
    expect(section.querySelector('h1').textContent).toBe('Renamed');
    expect(section.querySelector('strong')).toBeTruthy();
    expect(document.contains(p)).toBe(false); // type changed -> replaced
    expect(section.querySelector('em').textContent).toBe('end');
    expect(document.contains(span)).toBe(true); // same position, same type -> kept
  });
});

